// Engine host (design §4.10): runs a package's processes and trainers inside its worker and streams their frames to the
// main thread. Each package's worker.ts (generated by `atlas new`) is four lines:
//    import { serve } from '../../atlas/engine/host.ts';
//    import * as trainers from './trainer.ts';
//    import * as processes from './process.ts';
//    serve({ trainers, processes });
//
// Frames come from process/record.ts stepper(), the same frame source localRunner's recorder uses, so anchors, draws,
// `keep` merging and maxFrames are identical and a worker tape hashes equal to a local tape (acceptance 4).
// Scheduling: one cooperative loop for every open stream, in slices of <= sliceMs (8 ms), yielding a macrotask between
// slices so control messages (pause, set lr, cancel) are handled within one slice. Frames are batched to maxFps (default
// 30) per stream; a batch is posted at once after a control took effect, on pause, and at the end.
// Pure TS: no DOM. createHost() also runs in Node (tests drive it over a MessageChannel).
import type { Control, ProcessDef } from '../types/process.ts';
import type { EngineReply, EngineRequest } from '../types/engine.ts';
import type { TrainerDef } from '../types/train.ts';
import { stepper, type Stepper } from '../process/record.ts';
import { trainingProcess } from '../train/trainer.ts';
import { derivedFields, ENGINE_ERRORS, FramePacker, mergeControls, schemaJson, type OpenArgs, type PackStats } from './protocol.ts';

// ------------------------------------------------------------------ module registry (mirrors scripts/atlas/load.ts)
export const isProcessDef = (v: unknown): v is ProcessDef<any, any, any> =>
	!!v && typeof v === 'object' && typeof (v as ProcessDef).run === 'function' && typeof (v as ProcessDef).id === 'string' && !!(v as ProcessDef).phases && !!(v as ProcessDef).schema;

export const isTrainerDef = (v: unknown): v is TrainerDef<any, any, any, any> =>
	!!v &&
	typeof v === 'object' &&
	typeof (v as TrainerDef).id === 'string' &&
	typeof (v as TrainerDef).model === 'function' &&
	typeof (v as TrainerDef).batch === 'function' &&
	typeof (v as TrainerDef).loss === 'function';

export interface ServeModules {
	/** `import * as trainers from './trainer.ts'`: every TrainerDef export, registered as 'train:<id>' */
	trainers?: Record<string, unknown>;
	/** `import * as processes from './process.ts'`: every ProcessDef export, registered under its id */
	processes?: Record<string, unknown>;
	/** extra request/response methods for { type: 'call' } (the host answers 'ping' and 'processes' itself) */
	calls?: Record<string, (args: unknown) => unknown>;
}

/** The process table a package exposes: the same keys the Node loader (scripts/atlas/load.ts) registers. */
export function registerModules(m: ServeModules): Record<string, ProcessDef<any, any, any>> {
	const out: Record<string, ProcessDef<any, any, any>> = {};
	const add = (key: string, p: ProcessDef<any, any, any>) => {
		if (out[key] && out[key] !== p) throw new Error(`engine: two processes are registered as '${key}'`);
		out[key] = p;
	};
	for (const v of Object.values(m.processes ?? {})) if (isProcessDef(v)) add(v.id, v);
	for (const v of Object.values(m.trainers ?? {})) if (isTrainerDef(v)) add(`train:${v.id}`, trainingProcess(v));
	return out;
}

// ------------------------------------------------------------------ host
export type Post = (msg: EngineReply, transfer: ArrayBuffer[]) => void;

export interface HostOpts {
	/** work per slice before yielding (default 8 ms) */
	sliceMs?: number;
	/** run fn as a fresh macrotask (default: MessageChannel in browsers, setImmediate in Node, else setTimeout) */
	schedule?: (fn: () => void) => void;
	now?: () => number;
	/** 'worker' (default inside a worker) or 'main' (a host used on the main thread or in Node) */
	where?: 'worker' | 'main';
}

interface Stream {
	id: number;
	channel: string;
	p: ProcessDef<any, any, any>;
	args: OpenArgs;
	s: Stepper;
	running: boolean;
	stepBudget: number;
	queue: Control[];
	packer: FramePacker;
	minGap: number;
	lastPost: number;
	flushNow: boolean;
	/** packer totals already added to the host stats */
	counted: PackStats;
	/** controls waiting for the frame that applies them (for the control log) */
	pendingLog: ControlRecord[];
}

/** One control as the host saw it: the frame count when it arrived and when it took effect. 'set'/'input' take effect
 *  in the first frame produced after they arrive; 'pause' stops production before the next frame. */
export interface ControlRecord {
	channel: string;
	type: Control['type'];
	/** frames this stream had produced when the control arrived */
	receivedAt: number;
	/** index of the first frame produced with it (set/input), or the frame count when production stopped (pause) */
	appliedAt: number;
	/** ms between arrival and the first frame that carries it (set/input), or 0 */
	ms: number;
	t: number;
}

export interface Host {
	handle(msg: EngineRequest): void;
	/** stop every stream (no more messages are posted) */
	close(): void;
	readonly processes: string[];
	/** open streams by channel (tests, the performance page) */
	streams(): { channel: string; id: number; running: boolean; frames: number }[];
	/** totals over all streams: frames posted, typed arrays copied and re-used, bytes transferred, messages */
	readonly stats: PackStats & { messages: number };
	/** the last 64 controls (also answered by the 'stats' call) */
	readonly controls: ControlRecord[];
}

function defaultSchedule(): (fn: () => void) => void {
	const g = globalThis as { setImmediate?: (fn: () => void) => unknown; MessageChannel?: typeof MessageChannel; window?: unknown; document?: unknown };
	if (typeof g.setImmediate === 'function') return (fn) => void g.setImmediate!(fn);
	if (typeof g.MessageChannel === 'function') {
		// a zero-delay macrotask (setTimeout(0) is clamped to >= 4 ms once nested); messages from the main thread are
		// queued as tasks too, so a control posted during a slice is handled before the next slice
		const ch = new g.MessageChannel();
		const q: (() => void)[] = [];
		ch.port1.onmessage = () => q.shift()?.();
		return (fn) => {
			q.push(fn);
			ch.port2.postMessage(0);
		};
	}
	return (fn) => void setTimeout(fn, 0);
}

export function createHost(mods: ServeModules, post: Post, o: HostOpts = {}): Host {
	const table = registerModules(mods);
	const calls = mods.calls ?? {};
	const sliceMs = o.sliceMs ?? 8;
	const now = o.now ?? (() => (typeof performance !== 'undefined' ? performance.now() : Date.now()));
	const schedule = o.schedule ?? defaultSchedule();
	const where = o.where ?? 'worker';
	const streams = new Map<string, Stream>();
	const stats = { frames: 0, copies: 0, reused: 0, bytes: 0, messages: 0 };
	const controls: ControlRecord[] = [];
	const logControl = (r: ControlRecord) => {
		controls.push(r);
		if (controls.length > 64) controls.shift();
	};
	let closed = false;
	let scheduled = false;

	const send = (msg: EngineReply, transfer: ArrayBuffer[] = []) => {
		if (closed) return;
		stats.messages++;
		post(msg, transfer);
	};

	const wants = (st: Stream) => !st.s.done && (st.running || st.stepBudget > 0);

	const flush = (st: Stream, done = false) => {
		if (st.packer.size === 0 && !done) return;
		const { frames, transfer } = st.packer.take();
		const tot = st.packer.total;
		stats.frames += frames.length;
		stats.copies += tot.copies - st.counted.copies;
		stats.reused += tot.reused - st.counted.reused;
		stats.bytes += tot.bytes - st.counted.bytes;
		st.counted = { ...tot };
		st.lastPost = now();
		st.flushNow = false;
		send(done ? { id: st.id, type: 'frames', frames, done: true } : { id: st.id, type: 'frames', frames }, transfer);
	};

	const end = (st: Stream) => {
		st.s.cancel();
		if (streams.get(st.channel) === st) streams.delete(st.channel);
	};

	const fail = (st: Stream, e: unknown) => {
		flush(st);
		send({ id: st.id, type: 'error', code: ENGINE_ERRORS.processError, message: e instanceof Error ? e.message : String(e) });
		end(st);
	};

	const makeStepper = (st: Pick<Stream, 'p' | 'args'>, seed: number) => {
		const a = st.args;
		return stepper(st.p, a.input, (a.opt ?? {}) as Record<string, unknown>, {
			seed,
			detail: a.detail,
			recordDraws: a.recordDraws,
			keyEvery: a.keyEvery,
			maxFrames: a.maxFrames,
			keep: a.keep
		});
	};

	/** produce one frame of one stream; false when the stream ended */
	const produce = (st: Stream): boolean => {
		const c = st.queue.shift();
		let f;
		try {
			f = st.s.next(c);
		} catch (e) {
			fail(st, e);
			return false;
		}
		if (c) {
			st.flushNow = true; // a control took effect: show it at once
			const r = st.pendingLog.shift();
			if (r) {
				r.appliedAt = st.s.count - (f ? 1 : 0);
				r.ms = now() - r.t;
				logControl(r);
			}
		}
		if (!f) {
			// the run is over; the stream stays open (a 'reset' starts a fresh run, as recorder() allows) until 'cancel'
			st.stepBudget = 0;
			flush(st, true);
			return false;
		}
		st.packer.add(f);
		if (st.stepBudget > 0) st.stepBudget--;
		return true;
	};

	const tick = () => {
		scheduled = false;
		if (closed) return;
		const t0 = now();
		let active = [...streams.values()].filter(wants);
		let urgent = false;
		while (active.length && now() - t0 < sliceMs && !urgent) {
			for (const st of active) {
				produce(st);
				// a control just took effect: end the slice and post its first frame now
				if (st.flushNow) urgent = true;
			}
			active = [...streams.values()].filter(wants);
		}
		const t = now();
		for (const st of [...streams.values()]) {
			if (st.packer.size && (st.flushNow || !wants(st) || t - st.lastPost >= st.minGap)) flush(st);
		}
		kick();
	};

	const kick = () => {
		if (scheduled || closed) return;
		if (![...streams.values()].some(wants)) return;
		scheduled = true;
		schedule(tick);
	};

	const open = (msg: Extract<EngineRequest, { type: 'stream' }>) => {
		const old = streams.get(msg.channel);
		if (old) end(old); // a newer request on a channel supersedes the older one
		const p = table[msg.args?.process];
		if (!p) {
			send({ id: msg.id, type: 'error', code: ENGINE_ERRORS.unknownProcess, message: `no process '${msg.args?.process}' in this worker (have ${Object.keys(table).join(', ') || 'none'})` });
			return;
		}
		const args = msg.args as OpenArgs;
		const fps = msg.maxFps && msg.maxFps > 0 ? msg.maxFps : 30;
		let s: Stepper;
		try {
			s = makeStepper({ p, args }, args.seed);
		} catch (e) {
			send({ id: msg.id, type: 'error', code: ENGINE_ERRORS.processError, message: e instanceof Error ? e.message : String(e) });
			return;
		}
		const st: Stream = {
			id: msg.id,
			channel: msg.channel,
			p,
			args,
			s,
			running: args.autorun === true,
			stepBudget: 0,
			queue: [],
			packer: new FramePacker(derivedFields(p.schema)),
			minGap: 1000 / fps,
			lastPost: -Infinity,
			flushNow: false,
			counted: { frames: 0, copies: 0, reused: 0, bytes: 0 },
			pendingLog: []
		};
		streams.set(msg.channel, st);
		send({ id: msg.id, type: 'schema', schema: schemaJson(p.schema) });
		kick();
	};

	const control = (msg: Extract<EngineRequest, { type: 'control' }>) => {
		const st = streams.get(msg.channel);
		if (!st) return;
		const c = msg.control;
		const rec: ControlRecord = { channel: st.channel, type: c.type, receivedAt: st.s.count, appliedAt: st.s.count, ms: 0, t: now() };
		switch (c.type) {
			case 'pause':
				st.running = false;
				flush(st);
				logControl(rec);
				return;
			case 'resume':
				st.running = true;
				return kick();
			case 'step':
				st.stepBudget += Math.max(0, Math.floor(c.n));
				return kick();
			case 'reset': {
				// a fresh run (new stepper, fresh rng with the given seed): the client starts a new TapeStore when the
				// schema arrives again, exactly like recorder()'s reset
				st.s.cancel();
				st.packer.take();
				st.queue = [];
				st.pendingLog = [];
				st.stepBudget = 0;
				if (c.seed !== undefined) st.args = { ...st.args, seed: c.seed };
				try {
					st.s = makeStepper(st, st.args.seed);
				} catch (e) {
					return fail(st, e);
				}
				send({ id: st.id, type: 'schema', schema: schemaJson(st.p.schema) });
				return kick();
			}
			default:
				// a later 'reset' restarts on the latest input and options (as recorder() does; K0)
				if (c.type === 'input') st.args = { ...st.args, input: c.input };
				else if (c.type === 'set') st.args = { ...st.args, opt: { ...((st.args.opt ?? {}) as object), ...c.opt } };
				if (c.type === 'set' && st.queue[st.queue.length - 1]?.type === 'set') st.pendingLog.pop(); // merged into one
				mergeControls(st.queue, c);
				st.pendingLog.push(rec);
				return kick();
		}
	};

	const call = (msg: Extract<EngineRequest, { type: 'call' }>) => {
		try {
			let data: unknown;
			if (msg.method === 'ping') data = { where, processes: Object.keys(table) };
			else if (msg.method === 'stats') data = { ...stats, controls: controls.slice() };
			else if (msg.method === 'processes') data = Object.keys(table);
			else if (calls[msg.method]) data = calls[msg.method](msg.args);
			else return send({ id: msg.id, type: 'error', code: ENGINE_ERRORS.unknownMethod, message: `no method '${msg.method}'` });
			send({ id: msg.id, type: 'result', data });
		} catch (e) {
			send({ id: msg.id, type: 'error', code: ENGINE_ERRORS.callError, message: e instanceof Error ? e.message : String(e) });
		}
	};

	return {
		get processes() {
			return Object.keys(table);
		},
		get stats() {
			return stats;
		},
		get controls() {
			return controls;
		},
		streams: () => [...streams.values()].map((s) => ({ channel: s.channel, id: s.id, running: s.running, frames: s.s.count })),
		handle(msg: EngineRequest) {
			if (closed || !msg || typeof msg !== 'object') return;
			switch (msg.type) {
				case 'stream':
					return open(msg);
				case 'control':
					return control(msg);
				case 'cancel': {
					const st = streams.get(msg.channel);
					if (st) end(st);
					return;
				}
				case 'call':
					return call(msg);
				default:
					send({ id: (msg as { id?: number }).id ?? -1, type: 'error', code: ENGINE_ERRORS.badRequest, message: `unknown request type '${(msg as { type?: string }).type}'` });
			}
		}
		,
		close() {
			for (const st of [...streams.values()]) end(st);
			closed = true;
		}
	};
}

/** True inside a dedicated or shared worker. */
export function inWorker(): boolean {
	const g = globalThis as { WorkerGlobalScope?: unknown; document?: unknown; importScripts?: unknown };
	return typeof g.WorkerGlobalScope !== 'undefined' && g.document === undefined;
}

/**
 * Serve a package's processes from the worker this module runs in. Posts { type: 'status', status: 'ready' } once the
 * modules are registered (the client's "the worker started" signal), or status 'error' with the reason. Outside a worker
 * (Node, the main thread) it does nothing and returns null, so importing a worker.ts by mistake is harmless.
 */
export function serve(mods: ServeModules, o: HostOpts = {}): Host | null {
	if (!inWorker()) return null;
	const scope = globalThis as unknown as { postMessage(m: unknown, t?: Transferable[]): void; addEventListener(type: 'message', fn: (e: MessageEvent) => void): void };
	let host: Host;
	try {
		host = createHost(mods, (m, t) => scope.postMessage(m, t), { ...o, where: 'worker' });
	} catch (e) {
		scope.postMessage({ type: 'status', status: 'error', message: e instanceof Error ? e.message : String(e) } satisfies EngineReply);
		return null;
	}
	scope.addEventListener('message', (e: MessageEvent) => host.handle(e.data as EngineRequest));
	scope.postMessage({ type: 'status', status: 'ready' } satisfies EngineReply);
	return host;
}
